                        (add_p[15] & add_p[14] & add_p[13] & add_p[12] & add_p[11] & add_p[10] & add_g[9]) |
                        (add_p[15] & add_p[14] & add_p[13] & add_p[12] & add_p[11] & add_p[10] & add_p[9] & add_g[8]);
    assign block_g[2] = add_g[23] | (add_p[23] & add_g[22]) |
                        (add_p[23] & add_p[22] & add_g[21]) |
